from mk import *
from lib import fbd
STRICT["on"] = True
from lib import mini
import math
G = 6.67e-11; M = 5.98e24; R = 6.37e6
v = math.sqrt(G * M / (R + 1.9e5))
clip = lambda y: max(-1, min(1, y))
F2 = lambda x: clip(0.012 / (x + 0.08) ** 2 - 0.0016 / (1.04 - x) ** 2 * 0.9)

def fig():
    g = Fig(640, 400, "למעלה: כדור הארץ, המרכז, נקודה D על הקו לירח, המרחק rE ממרכז כדור הארץ ל-D, והמרחק rM מ-D למרכז הירח. למטה: ארבעה גרפים של שקול כוחות הכבידה כפונקציה של המרחק r ממרכז כדור הארץ. גרף 1: קבוע וחיובי ואז קפיצה לשלילי. גרף 2: יורד מערך חיובי גדול ליד כדור הארץ, חוצה את האפס, ושואף לערך שלילי גדול ליד הירח. גרף 3: קו ישר יורד. גרף 4: יורד מערך חיובי גדול לערך שלילי קטן וקבוע כמעט")
    ex, ey, mx = 110, 95, 560
    g.circle(ex, ey, 60, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(ex, ey - 70, "כדור הארץ")
    g.circle(mx, ey, 16, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(mx, ey - 26, "הירח")
    g.dot(ex, ey); g.dot(mx, ey); g.line(ex, ey, mx, ey, width=1.1, dash="5 4")
    dx = 250; g.ball(dx, ey, r=5); g.text(dx, ey - 12, "D")
    g.dim(ex, ey + 26, dx, ey + 26, "rE", ext=False, label_dy=6); g.dim(dx, ey + 26, mx, ey + 26, "rM", ext=False, label_dy=6)
    defs = [("1", dict(segs=[[(0.02, 0.7), (0.78, 0.7), (0.78, -0.18), (0.95, -0.18)]])),
            ("2", dict(fn=None, segs=[(F2, 0.0, 1.0)])),
            ("3", dict(pts=[(0.0, 0.9), (1.0, -0.9)])),
            ("4", dict(segs=[(lambda x: clip(0.01 / (x + 0.06) ** 2 - 0.25), 0.0, 1.0)]))]
    for i, (lab, kw) in enumerate(defs):
        mini(g, 490 - i * 150, 290, 110, 60, label=lab, xl="r", yl="ΣF", neg=True, **kw)
    return g

E(id="bagrut-2019-q6", year=2019, label="2019 שאלה 6", topic="gravitation", sub="grav-law", diff=3, fig=fig,
  stem=r"ביולי 1969, במשימת אפולו 11, נשלחה חללית אל הירח. בדרך היא נכנסה ל\"מסלול ביניים\" מעגלי סביב כדור הארץ ונעה בו כמו לוויין, ומשם המשיכה לירח. במשימה הזו נחתו בפעם הראשונה בני אדם על הירח. מסת החללית $m$, והגובה של מסלול הביניים מעל פני כדור הארץ $h = 190\,\text{km}$. בסעיפים א עד ג רק כדור הארץ משפיע על החללית. נתונים: מסת כדור הארץ $5.98 \times 10^{24}\,\text{kg}$, רדיוס כדור הארץ $6.37 \times 10^6\,\text{m}$.",
  parts=[
    P("א", r"מה גודל המהירות של החללית במסלול הביניים?", num(v, "m/s", tol=1), ["principle", "algebra"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה נותן את התאוצה אל המרכז. רדיוס המסלול הוא הרדיוס ועוד הגובה", r"r = R + h = 6.56 \times 10^6\,\text{m},\qquad v = \sqrt{\frac{GM}{r}} = \sqrt{\frac{6.67 \times 10^{-11} \cdot 5.98 \times 10^{24}}{6.56 \times 10^6}} \approx 7.8 \times 10^3\,\text{m/s}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \frac{v^2}{r}"),
    ], r"$v \approx 7.8 \times 10^3\,\text{m/s}$", key=r"v=7788 m/s"),
    P("ב", r"תלמידה טוענת שלפי החוק הראשון של ניוטון החללית במסלול הביניים נמצאת בשיווי משקל, כי היא נעה במהירות שגודלה קבוע. האם היא צודקת? נמקו.", choice(["צודקת", "לא צודקת"], 1), ["principle"], [
        S(r"המהירות היא וקטור", r"הגודל שלה קבוע, אבל הכיוון משתנה כל הזמן, ולכן יש תאוצה אל המרכז", r"a_R = \frac{v^2}{r} \ne 0"),
        S(r"החוק הראשון", r"שיווי משקל יש רק כשהמהירות קבועה גם בגודל וגם בכיוון. כאן הכבידה היא כוח שקול שלא אפס", r"\Sigma F = \frac{GMm}{r^2} \ne 0"),
    ], r"לא צודקת: הכיוון של המהירות משתנה, ולכן יש כוח שקול", key=r"velocity is a vector"),
    P("ג1", r"אם המסה של החללית במסלול הביניים הייתה גדולה יותר, האם גודל המהירות שלה היה גדל, קטן או לא משתנה? נמקו.", choice(["גדל", "קטן", "לא משתנה"], 2), ["principle"], [
        S(r"המסה מצטמצמת", r"ממשוואת הכוחות, המהירות תלויה רק במסת כדור הארץ וברדיוס", r"v = \sqrt{\frac{GM_E}{R_E + h}}"),
    ], r"לא משתנה", key=r"v=√(GME/(RE+h))"),
    P("ג2", r"אם המסה של החללית הייתה גדולה יותר, האם האנרגיה המכנית הכוללת שלה הייתה גדלה, קטנה או לא משתנה? שימו לב לסימן של האנרגיה.", choice(["גדלה", "קטנה", "לא משתנה"], 1), ["principle", "signs"], [
        S(r"האנרגיה הכוללת במסלול", r"היא שלילית, ופרופורציונית למסה", r"E = -\frac{GMm}{2r}", eq=r"U = -\frac{GMm}{r}"),
        S(r"מסה גדולה יותר", r"הגודל של מספר שלילי גדל, ולכן המספר עצמו קטן", r"m\uparrow \;\Rightarrow\; E\downarrow"),
    ], r"קטנה, כלומר נעשית שלילית יותר", key=r"E=−GMm/2r"),
    P("ד", r"החללית המשיכה ממסלול הביניים למסלול סביב הירח, לאורך הקו שמחבר את מרכז כדור הארץ למרכז הירח. הנקודה $D$ נמצאת על הקו הזה (ראו תרשים). בסעיפים ד ו-ה רק כדור הארץ והירח משפיעים על החללית. מה השקול של כוחות הכבידה על החללית בנקודה $D$, $\Sigma F_G$, בעזרת $M_E$, $M_M$, $r_E$, $r_M$, $G$ ו-$m$? הכיוון החיובי הוא לכיוון כדור הארץ.", choice([r"$\frac{GM_E m}{r_E^2} - \frac{GM_M m}{r_M^2}$", r"$\frac{GM_E m}{r_E^2} + \frac{GM_M m}{r_M^2}$", r"$\frac{GM_M m}{r_M^2} - \frac{GM_E m}{r_E^2}$", r"$\frac{G(M_E - M_M)\,m}{(r_E + r_M)^2}$"], 0), ["fbd", "signs"], [
        S(r"שני כוחות בכיוונים הפוכים", r"כדור הארץ מושך את החללית אליו, בכיוון החיובי. הירח מושך אותה אליו, בכיוון ההפוך", r"\Sigma F_G = \frac{GM_E m}{r_E^2} - \frac{GM_M m}{r_M^2}", eq=r"F = \frac{GMm}{r^2}"),
    ], r"$\Sigma F_G = \frac{GM_E m}{r_E^2} - \frac{GM_M m}{r_M^2}$", key=r"ΣFG = GMEm/rE² − GMMm/rM²"),
    P("ה", r"לפניכם ארבעה גרפים מקורבים של השקול $\Sigma F_G$ כפונקציה של המרחק $r$ של החללית ממרכז כדור הארץ. איזה גרף מתאר נכון את השקול בדרך ממסלול הביניים לירח?", choice(["1", "2", "3", "4"], 1), ["graph", "principle"], [
        S(r"ליד כדור הארץ", r"הכוח של כדור הארץ גדול מאוד, והשקול חיובי וגדול", r"\Sigma F_G \gg 0"),
        S(r"ליד הירח", r"הכוח של הירח גובר, והשקול שלילי וגדל בגודלו", r"\Sigma F_G \ll 0"),
        S(r"באמצע", r"השקול משתנה ברציפות, וחוצה את האפס בנקודה אחת", r"\Sigma F_G(r_0) = 0"),
    ], r"גרף 2", key=r"graph 2 correct"),
  ],
  concepts=["מהירות במסלול", "החוק הראשון של ניוטון", "אנרגיה במסלול", "שקול כוחות כבידה"],
  summary=r"אפולו 11: המהירות במסלול הביניים, למה אין שיווי משקל, והשקול של כוחות הכבידה של כדור הארץ והירח לאורך הדרך.",
  review="הנחה שלי.\nבסעיף ד התלמיד בוחר את הביטוי הנכון מתוך ארבעה, ובשאלה כתוב מה הכיוון החיובי.\nמה לבדוק: רק לאשר.")
